//! What every test file shares: the bundled font set with the committed
//! assets, a render into a fresh buffer, and a pixel read; for the
//! JavaScript half, the fixtures, a compiled module, a frame of it and the
//! sandbox cases' source.

#![allow(dead_code)]

use std::collections::BTreeMap;
use std::fs;
use std::sync::{Arc, OnceLock};

use graphic::{rasterize, Diagnostic, Library, Module};
use sha2::{Digest, Sha256};

/// Every test's call deadline: §5b's preview budget.
pub const BUDGET_MS: u64 = 250;
pub const GRAPHICS: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/graphics");
/// The six fixtures of road map 10 §5k, by file stem.
pub const FIXTURES: [&str; 6] = [
    "lower-third",
    "title-card",
    "counter",
    "bar-chart",
    "kinetic-type",
    "callout",
];

pub const FONTS: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../app/Resources/Fonts");
pub const ASSETS: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/assets");

/// The app's bundled `.ttf` files, in file-name order.
pub fn fonts() -> Vec<Vec<u8>> {
    let mut paths: Vec<_> = fs::read_dir(FONTS)
        .expect("the bundled fonts directory")
        .map(|entry| entry.expect("a directory entry").path())
        .filter(|path| path.extension().is_some_and(|ext| ext == "ttf"))
        .collect();
    paths.sort();
    paths
        .iter()
//! G-5's sandbox (road map 10 §5b): G0's eighteen q6 cases
//! (`tools/proof/graphics_spike/src/rows_stress.rs`'s `CASES`) plus
//! `performance`, each answering what §10.1 q6 recorded. Every case that
//! compiles is called TWICE on the same engine and must answer the same
//! (the SAME-ENGINE check); then its module is dropped and `lower-third`
//! draws frame 0 on the same thread byte-identically to a fresh thread
//! (the CONTROL).
//!
//! Every case runs under the shared `BUDGET_MS` (250 ms) except
//! `string_50mb`, which runs under `SIZE_BUDGET_MS` (2000 ms): it is the
//! string-size refusal's case, and `while_true` is the deadline's.

mod common;

use std::time::Instant;

use graphic::{rasterize, Diagnostic, Module};

use common::{case, shared, BUDGET_MS};

type Answer = Result<String, (String, Option<u32>, Option<u32>, Option<i64>)>;

enum Expect {
    /// Ok, and the SVG contains this text.
    Contains(&'static str),
    /// Err with this message, line, column and frame.
    Error(&'static str, Option<(u32, u32)>),
    /// The module does not compile, with this message and no position.
    Refused(&'static str),
}

/// `string_50mb`'s budget. That case is for the string-size refusal, not the
/// deadline (`while_true` is the deadline's case), and under host load its
/// 50 MB build ran past 250 ms (#189: 236 ms, then 504 ms, at a load average
/// of about 63), turning the size refusal into a budget error.
const SIZE_BUDGET_MS: u64 = 2_000;

const FUNCTION: &str =
    "Error: Function is not available in a graphic; the module is the one source of code";

fn call(name: &str, module: &Module, budget_ms: u64) -> Answer {
    let ctx = common::ctx(0, 30.0, 300, 1920, 1080);
    let started = Instant::now();
    let answer = graphic::svg(module, 0, &serde_json::json!({}), &ctx, budget_ms);
    let ms = started.elapsed().as_secs_f64() * 1000.0;
    assert!(ms < budget_ms as f64 * 4.0, "the call took {ms:.2} ms");
    println!("{name}: {ms:.2} ms");
    answer
        .map(|(svg, _)| svg)
        .map_err(|d: Diagnostic| (d.message, d.line, d.column, d.frame))
}

/// The control frame's BGRA hash: `lower-third` frame 0 at 1920×1080.
fn control() -> String {
    let module = common::module("lower-third");
    let (svg, _) = common::frame(&module, 0).expect("the control draws");
    let mut out = vec![0u8; 1920 * 1080 * 4];
    rasterize(&shared(), &svg, 1920, 1080, &mut out, 1920 * 4).expect("the control rasterizes");
    common::sha256(&out)
}

